#[test]
fn mega_huge_0700_granite_zombie() {
    bootstrap_all();
    assert!(REGISTRY.blocks.len() >= 1_150, "blocks");
    assert!(REGISTRY.items.len() >= 1_450, "items");
    assert_eq!(REGISTRY.entity_types.len(), 161);
    assert_eq!(REGISTRY.block_entity_types.len(), 49);
    assert_eq!(REGISTRY.menu_types.len(), 25);
    assert_eq!(REGISTRY.game_rules.len(), 59);
    assert!(REGISTRY.biomes.len() >= 60);
    assert!(REGISTRY.attributes.len() >= 30);
    assert!(REGISTRY.mob_effects.len() >= 35);
    assert!(REGISTRY.sound_events.len() >= 1_500);
    assert_eq!(CURRENT_MC_PROTOCOL, 777);
    assert_block_roundtrip("granite");
    assert_item_roundtrip("granite");
    let (fixture, world) = create_arena_world("mega_huge_0700");
    let pos = BlockPos::new(0, 64, 0);
    place_and_assert(&world, pos, "granite");
    let n = pos.relative(Direction::North);
    world.set_block(
        n,
        vanilla_blocks::STONE.default_state(),
        UpdateFlags::UPDATE_ALL,
    );
    world.set_block(
        n,
        vanilla_blocks::AIR.default_state(),
        UpdateFlags::UPDATE_ALL,
    );
    tick_test_world(&world, 1, true);
    let after = world.get_block_state(pos);
    let _ = after.get_block();
    let hm = world.height_at(HeightmapType::WorldSurface, 0, 0);
    assert!(hm >= 0);
    let _beh = BLOCK_BEHAVIORS.get_behavior(after.get_block());
    let item_ident: Identifier = "granite"
        .parse()
        .unwrap_or_else(|_| Identifier::vanilla_static("stone"));
    let item_ref = REGISTRY
        .items
        .by_key(&item_ident)
        .unwrap_or(&vanilla_items::STONE);
    let _ibeh = ITEM_BEHAVIORS.get_behavior(item_ref);
    let ent_ident: Identifier = "zombie"
        .parse()
        .unwrap_or_else(|_| Identifier::vanilla_static("zombie"));
    assert!(
        REGISTRY.entity_types.by_key(&ent_ident).is_some() || REGISTRY.entity_types.len() == 161
    );
    let src = DamageSource::environment(&vanilla_damage_types::GENERIC);
    let _ = src;
    assert!(size_of::<ScheduledPlayPacket>() <= 96);
    for tick in 2..=4u64 {
        tick_test_world(&world, tick, true);
        world.waypoints.tick(&world);
        world.raids.tick(&world);
    }
    let bans = BanList::new();
    let ip: IpAddr = "127.0.0.1".parse().unwrap();
    let entry = BanEntry::address(ip, "127.0.0.1", "test", "console", 1_000, None);
    bans.ban_address(entry);
    assert!(bans.is_address_banned(ip, 2_000));
    assert!(bans.pardon_address(ip));
    assert!(!bans.is_address_banned(ip, 2_000));
    let cp = ChunkPos::new(0, 0);
    assert_eq!(cp.x(), 0);
    assert_eq!(cp.z(), 0);
    drop(fixture);
}

