#[test]
fn mega_comprehensive_all_blocks_items_entities_loop() {
    bootstrap_all();
    let (fixture, world) = create_arena_world("mega_comprehensive_loop");
    let mut placed = 0usize;
    for (id, block) in REGISTRY.blocks.iter() {
        let state = block.default_state();
        let got = state.get_block();
        assert_eq!(got.key, block.key, "block key mismatch for {}", id);
        let pos = BlockPos::new(
            (placed % 16) as i32,
            64 + ((placed / 16) % 8) as i32,
            ((placed / 256) % 16) as i32,
        );
        place_and_assert(&world, pos, &block.key.path);
        let _beh = BLOCK_BEHAVIORS.get_behavior(block);
        placed += 1;
        if placed > 200 {
            break;
        }
    }
    let mut item_checked = 0usize;
    for (id, item) in REGISTRY.items.iter() {
        let got = REGISTRY.items.by_key(&item.key).expect("item by_key");
        assert_eq!(got.key, item.key, "item {}", id);
        let _ibeh = ITEM_BEHAVIORS.get_behavior(item);
        item_checked += 1;
        if item_checked > 200 {
            break;
        }
    }
    let mut ent_checked = 0usize;
    for (id, et) in REGISTRY.entity_types.iter() {
        assert!(!et.key.path.is_empty(), "entity {}", id);
        ent_checked += 1;
        if ent_checked > 50 {
            break;
        }
    }
    for tick in 1..=10u64 {
        tick_test_world(&world, tick, true);
    }
    assert!(REGISTRY.recipe_types.len() >= 5);
    assert!(REGISTRY.loot_tables.len() >= 100);
    for special in [
        "sculk_sensor",
        "sculk_shrieker",
        "trial_spawner",
        "vault",
        "creaking_heart",
        "pale_oak_log",
        "cactus",
        "bamboo",
        "redstone_wire",
        "repeater",
        "comparator",
    ] {
        if let Some(b) = REGISTRY
            .blocks
            .by_key(&special.parse::<Identifier>().unwrap())
        {
            let _ = BLOCK_BEHAVIORS.get_behavior(b);
        }
    }
    drop(fixture);
}
